    const xgap = (xmax - xmin || 1) * .08, ygap = (ymax - ymin || 1) * .08; xmin -= xgap; xmax += xgap; ymin -= ygap; ymax += ygap;
    const nums = values?.filter(Number.isFinite) || [0, 1], vmin = Math.min(...nums), vmax = Math.max(...nums);
