    const mapped = points.map((p,i) => ({x:pad+(xs[i]-xmin)/(xmax-xmin)*(w-2*pad), y:h-pad-(ys[i]-ymin)/(ymax-ymin)*(h-2*pad), z:zs[i], i})).sort((a,b)=>a.z-b.z);
    if (opts.line) { ctx.lineWidth=opts.lineWidth||1.8; for(let i=1;i<mapped.length;i++){ctx.beginPath();ctx.moveTo(mapped[i-1].x,mapped[i-1].y);ctx.lineTo(mapped[i].x,mapped[i].y);ctx.strokeStyle=color(values?.[i] ?? i, vmin, vmax);ctx.stroke();} }
    mapped.forEach(p => { const radius=(opts.radius||2.6) + .5*(p.z-Math.min(...zs))/(Math.max(...zs)-Math.min(...zs)||1); ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);ctx.fillStyle=color(values?.[p.i] ?? p.i,vmin,vmax,opts.categorical);ctx.globalAlpha=opts.alpha||.82;ctx.fill(); }); ctx.globalAlpha=1;
