    ctx.textAlign="left";ctx.fillStyle="rgba(148,163,184,.7)";ctx.font="9px system-ui";const rowStep=Math.max(1,Math.ceil(rows/12)),colStep=Math.max(1,Math.ceil(cols/12));for(let i=0;i<rows;i+=rowStep)ctx.fillText(`${i+1}`,5,pad+(i+.58)*ch);for(let i=0;i<cols;i+=colStep)ctx.fillText(`${i+1}`,pad+(i+.4)*cw,17);
