    const xs=runs.map(r=>Number(r.load_ratio)),ys=runs.map(r=>Number(r.sparsity)),vals=runs.map(r=>Number(r.metrics?.tangent_overlap)||0),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),vmin=Math.min(...vals),vmax=Math.max(...vals);
