  function renderCurrent(){if(G.view==="data"){renderSummary();}else if(G.view==="plan")renderAnalysisPlan();else if(G.view==="training"){if(G.analysis){drawMetrics(G.analysis.metrics);renderGenerated();}}else if(G.view==="decoder")renderDecoder();else if(G.view==="representation")renderRepresentation();else if(G.view==="explorer")renderExplorer();else if(G.view==="metrics")renderScientific();else if(G.view==="sweeps")renderSweep();}

  async function refreshExperiments(selected) {
    const data=await api("/api/geometry/experiments");G.experiments=data.experiments||[];
    const options=G.experiments.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(String(x.dataset_type||x.dataset_source||"dataset").replaceAll("_"," "))}${x.dataset_variant?` · ${esc(x.dataset_variant.replaceAll('_',' '))}`:''}${x.trained?' · trained':''}${x.results_only?' · results only':''}</option>`).join("");
    const trainedOptions=G.experiments.filter(x=>x.trained).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("");
    const select=q("#geo-experiment-select");if(select){select.innerHTML='<option value="">Create or select an experiment</option>'+options;if(selected)select.value=selected;}
    qa(".geo-compare-select").forEach((el,index)=>{const old=el.value;el.innerHTML=`<option value="">Experiment ${String.fromCharCode(65+index)}</option>`+trainedOptions;if(old)el.value=old;});
    const suiteSelect=q("#geo-reproduction-suite");if(suiteSelect){const old=suiteSelect.value,labels=[...new Set(G.experiments.map(x=>x.run_label).filter(label=>label&&label.startsWith("paper-")))];suiteSelect.innerHTML='<option value="">Select a queued paper suite</option>'+labels.map(label=>`<option value="${esc(label)}">${esc(label)} · ${G.experiments.filter(x=>x.run_label===label).length}/20 runs</option>`).join("");if(labels.includes(old))suiteSelect.value=old;}
    populateZietlowSources();
  }

  function populateIdentity(config){const mapping={"#geo-name":"name","#geo-run-label":"run_label","#geo-paper-title":"paper_title","#geo-paper-citation":"paper_citation","#geo-paper-url":"paper_url","#geo-description":"description","#geo-hypothesis":"hypothesis"};Object.entries(mapping).forEach(([selector,key])=>{if(q(selector))q(selector).value=config[key]||"";});q("#geo-tags").value=(config.tags||[]).join(", ");if(q("#geo-study-preset"))q("#geo-study-preset").value=(config.paper_id==="zietlow2021"||config.paper_title===ZIETLOW_TITLE)?"zietlow2021":"";}

  async function loadExperiment(id) {if(!id){G.experiment=G.summary=G.analysis=G.scientific=null;renderSummary();renderQueue();return;}const data=await api(`/api/geometry/experiments/${encodeURIComponent(id)}`);G.experiment=data.experiment;G.summary=data.summary;G.analysis=data.analysis;G.scientific=data.scientific;G.projection=data.analysis?.projection||null;q("#geo-train-latent").value=G.experiment.latent_dim;q("#geo-latent-dim").value=G.experiment.latent_dim;populateIdentity(G.experiment);populateAnalysisPlan(G.experiment.analysis_plan);if(G.experiment.paper_protocol&&Object.keys(G.experiment.paper_protocol).length){q("#geo-paper-protocol").value=JSON.stringify(G.experiment.paper_protocol,null,2);q("#geo-paper-preset").value=G.experiment.paper_protocol.paper_id==="zietlow2021"?"zietlow_active":"";applyPaperProtocol(true);}else{q("#geo-paper-protocol").value="";q("#geo-paper-preset").value="";q("#geo-paper-mode-label").textContent="Paper reproduction mode: record Equation 30 polarization every 500 batches.";q("#geo-batch-assumption").textContent="For paper reproduction presets, batch size 256 is a declared dashboard assumption because the paper does not specify a batch size.";G.protocolApplied=false;q("#geo-protocol-status").textContent="Not applied";}renderSummary();if(G.analysis){drawMetrics(G.analysis.metrics);renderGenerated();renderExplorer();q("#geo-train-status").textContent=`Loaded ${G.analysis.model_label}`;q("#geo-train-progress").style.width="100%";q("#geo-train-percent").textContent="100%";}if(G.scientific){renderScientific();renderDecoder();renderRepresentation();}renderQueue();notify(`Loaded ${G.experiment.name}`,"success");}

  async function updateIdentity(){if(!G.experiment)return notify("Select an experiment first.","error");try{const payload={name:q("#geo-name").value,run_label:q("#geo-run-label").value,paper_title:q("#geo-paper-title").value,paper_citation:q("#geo-paper-citation").value,paper_url:q("#geo-paper-url").value,description:q("#geo-description").value,hypothesis:q("#geo-hypothesis").value,tags:q("#geo-tags").value.split(",").map(x=>x.trim()).filter(Boolean)},data=await api(`/api/geometry/experiments/${G.experiment.id}/identity`,{method:"PATCH",body:JSON.stringify(payload)});G.experiment=data.experiment;await refreshExperiments(G.experiment.id);notify("Experiment identity and paper provenance updated.","success");}catch(error){notify(error.message,"error");}}

  async function cloneActiveExperiment(){if(!G.experiment)return notify("Select an imported or existing experiment whose dataset should be reused.","error");const button=q("#geo-clone-experiment"),label=button.textContent;button.disabled=true;button.textContent="Registering…";try{const payload={name:q("#geo-name").value,run_label:q("#geo-run-label").value,tags:q("#geo-tags").value.split(",").map(x=>x.trim()).filter(Boolean),paper_title:q("#geo-paper-title").value,paper_citation:q("#geo-paper-citation").value,paper_url:q("#geo-paper-url").value,description:q("#geo-description").value,hypothesis:q("#geo-hypothesis").value,analysis_plan:selectedAnalyses(),paper_protocol:readPaperProtocol()},data=await api(`/api/geometry/experiments/${encodeURIComponent(G.experiment.id)}/clone`,{method:"POST",body:JSON.stringify(payload)});await refreshExperiments(data.experiment.id);await loadExperiment(data.experiment.id);q("#geo-paper-preset").value=data.experiment.paper_id==="zietlow2021"?"zietlow_active":"";G.protocolApplied=false;q("#geo-protocol-status").textContent="Registered · apply protocol";setView("models");notify("New untrained experiment registered from the active immutable dataset.","success");}catch(error){notify(error.message,"error");}finally{button.disabled=false;button.textContent=label;}}

