  function renderQueue(){
    const table=q("#geo-queue-table"),badge=q("#geo-queue-badge");if(!table||!badge)return;
    const activeCount=G.queue.filter(item=>["queued","running"].includes(item.status)).length,historyCount=G.queue.filter(item=>["complete","error"].includes(item.status)).length;
    badge.textContent=activeCount?`${activeCount} active · ${G.queue.length} total`:G.queue.length?`${G.queue.length} saved`:`Queue empty`;
    const clearButton=q("#geo-clear-queue-history");if(clearButton){clearButton.disabled=historyCount===0;clearButton.textContent=historyCount?`Clear queue history (${historyCount})`:"Clear queue history";}
    if(!G.queue.length){table.innerHTML='<div class="geo-empty geo-queue-empty"><div><b>No queued experiments</b>Select an untrained experiment and add its current training and analysis configuration.</div></div>';}
    else table.innerHTML=`<table><thead><tr><th>Order</th><th>Experiment</th><th>Configuration</th><th>Status</th><th>Progress</th><th>Added</th><th></th></tr></thead><tbody>${G.queue.map(item=>{const config=item.configuration||{},pct=Math.max(0,Math.min(100,Math.round(100*Number(item.progress||0)))),status=String(item.status||"queued"),order=status==="queued"?`#${item.position}`:status==="running"?"NOW":"—",stage=status==="running"?(item.stage||"running"):status,epoch=item.epoch?` · epoch ${item.epoch}`:"",added=item.created_at?new Date(item.created_at).toLocaleString():"",removable=status!=="running",budget=config.training_steps?`${config.training_steps} steps`:`${config.epochs??"?"} epochs`;return `<tr><td><span class="geo-queue-order">${esc(order)}</span></td><td><b class="geo-queue-name">${esc(item.experiment_name||item.experiment_id)}</b><span class="geo-queue-id">${esc(item.experiment_id)}</span></td><td>${esc(config.model_type||"model")} · ${esc(budget)} · ${esc(config.reconstruction_loss||"mse_sum")} · seed ${esc(config.seed??"?")}</td><td><span class="geo-queue-status" data-status="${esc(status)}">${esc(stage)}${esc(epoch)}</span>${item.error?`<span class="geo-queue-error">${esc(item.error)}</span>`:""}</td><td><div class="geo-queue-progress"><i style="width:${pct}%"></i></div><span>${pct}%</span></td><td>${esc(added)}</td><td><div class="geo-queue-actions"><button class="geo-btn small" data-queue-open="${esc(item.experiment_id)}">Open</button>${removable?`<button class="geo-btn small ghost" data-queue-remove="${esc(item.id)}">Remove</button>`:""}</div></td></tr>`;}).join("")}</tbody></table>`;
    const active=G.experiment&&G.queue.find(item=>item.experiment_id===G.experiment.id&&["queued","running"].includes(item.status));
    const trained=G.experiment&&G.experiments.find(item=>item.id===G.experiment.id)?.trained;
    const queueButton=q("#geo-add-queue");if(queueButton){queueButton.disabled=!G.experiment||!!active||!!trained||G.training;queueButton.textContent=active?(active.status==="queued"?`Queued #${active.position}`:"Running from queue"):trained?"Experiment already trained":"Add untrained experiment to queue";}
    const trainButton=q("#geo-train");if(trainButton&&!G.training)trainButton.disabled=!!active;
    if(active){const pct=Math.round(100*Number(active.progress||0));q("#geo-train-progress").style.width=`${pct}%`;q("#geo-train-percent").textContent=`${pct}%`;q("#geo-train-status").textContent=active.status==="queued"?`Waiting in queue · position ${active.position}`:`Queue · ${active.stage||"running"}${active.epoch?` · epoch ${active.epoch}`:""}`;q("#geo-epoch-badge").textContent=`Epoch ${active.epoch||0}`;}
  }

  async function refreshQueue(silent=true){if(G.queueRefreshing)return;G.queueRefreshing=true;try{const previous=new Map(G.queue.map(item=>[item.id,item.status])),data=await api("/api/geometry/training-queue");G.queue=data.items||[];renderQueue();const changed=G.queue.some(item=>previous.has(item.id)&&previous.get(item.id)!==item.status&&["complete","error"].includes(item.status));if(G.queueInitialized&&changed)await refreshExperiments(G.experiment?.id);G.queueInitialized=true;}catch(error){if(!silent)notify(error.message,"error");}finally{G.queueRefreshing=false;}}

  async function addExperimentToQueue(){if(!G.experiment)return notify("Select an untrained experiment first.","error");if(q("#geo-paper-protocol").value.trim()&&!G.protocolApplied)return notify("Apply the paper protocol before queueing so the saved settings match the run.","error");const button=q("#geo-add-queue"),label=button.textContent;button.disabled=true;button.textContent="Adding…";try{if(!await saveWorkflowPlan(false))return;await api("/api/geometry/training-queue",{method:"POST",body:JSON.stringify({experiment_id:G.experiment.id,training_config:trainingConfig(),analysis_config:queueAnalysisConfig()})});await refreshQueue(false);notify(`${G.experiment.name} added to the persistent queue.`,"success");}catch(error){notify(error.message,"error");}finally{button.textContent=label;renderQueue();}}

  async function removeQueueItem(queueId){try{await api(`/api/geometry/training-queue/${encodeURIComponent(queueId)}`,{method:"DELETE"});await refreshQueue(false);notify("Queue entry removed.","success");}catch(error){notify(error.message,"error");}}

