  async function applyProjection(){if(!G.experiment||!G.analysis)return notify("Train a model first.","error");const method=q("#geo-projection").value;try{q("#geo-apply-projection").disabled=true;const result=await api(`/api/geometry/experiments/${G.experiment.id}/projection`,{method:"POST",body:JSON.stringify({method})});G.projection=result.projection;renderExplorer();notify(`${result.method} projection ready.`,"success");}catch(error){notify(error.message,"error");}finally{q("#geo-apply-projection").disabled=false;}}

