  async function runScientific(automatic=false){if(!G.experiment||!G.analysis){notify("Train a model first.","error");return false;}if(G.experiment.results_only){notify("This results-only bundle can be inspected but not recomputed. Import the complete bundle for reanalysis.","error");return false;}const buttons=[q("#geo-run-science"),q("#geo-decoder-compute")];buttons.forEach(x=>x.disabled=true);try{const started=await api(`/api/geometry/experiments/${G.experiment.id}/scientific-analysis`,{method:"POST",body:JSON.stringify({maximum_samples:Number(q("#geo-science-samples").value),topology_points:Number(q("#geo-topology-points").value),seed:Number(q("#geo-train-seed").value),analysis_plan:selectedAnalyses(),paper_metrics:q("#geo-paper-metrics").checked,maximum_test_samples:Number(q("#geo-paper-test-samples").value)})});while(true){await sleep(900);const job=(await api(`/api/geometry/training/${started.job_id}`)).job,pct=Math.round(100*(job.progress||0));q("#geo-science-progress").style.width=`${pct}%`;q("#geo-science-percent").textContent=`${pct}%`;q("#geo-science-status").textContent=job.stage||job.status;if(job.status==="error")throw new Error(job.error);if(job.status==="complete"){G.scientific=job.scientific;renderScientific();renderDecoder();renderRepresentation();if(!automatic)notify("Selected scientific metrics and raw Jacobians saved.","success");return true;}}}catch(error){notify(error.message,"error");q("#geo-science-status").textContent="Analysis failed";return false;}finally{buttons.forEach(x=>x.disabled=false);}}

